#!/usr/bin/env python3
"""Generate isolated baseline and single frozen costly-toughness candidate."""
from pathlib import Path
import shutil,sys,json,hashlib
r=Path(__file__).resolve().parents[2];out=Path(sys.argv[1]).resolve()
for mode in ['baseline','candidate']:
 o=out/mode/'src';shutil.copytree(r/'src',o,dirs_exist_ok=True)
 if mode=='candidate':
  p=o/'simulation/ecology.zig';s=p.read_text().replace('pub const Plant = struct {','pub const Plant = struct {\n    toughness:f32=0,');a=s.index('pub fn grow(');b=s.index('\npub fn offspring',a);body=s[a:b];extra=body.replace('pub fn grow(', 'pub fn growTough(').replace('dt: f32) f32 {','dt: f32, d:f32) f32 {\n    if(d==0)return grow(biomass,temperature,optimum,water_depth_km,light,co2,dt);\n    if(!std.math.isFinite(d) or d<0 or d>1)return biomass;').replace('* 6 -','* 6 * (1-d) -');s=s[:b]+'\n'+extra+s[b:];s=s.replace('return .{ .optimum = std.math.clamp(parent.optimum','return .{ .toughness=parent.toughness, .optimum = std.math.clamp(parent.optimum');p.write_text(s)
  p=o/'simulation/foraging.zig';s=p.read_text();a=s.index('pub fn take(');b=s.index('\ntest ',a);body=s[a:b];extra=body.replace('pub fn take(', 'pub fn takeTough(').replace('seconds:f32) Bite {','seconds:f32,d:f32) Bite {\n    if(d==0)return take(cover,satiety,seconds);\n    if(!std.math.isFinite(d) or d<0 or d>1)return .{.after=cover};').replace('maximum_per_day*(@as(f64,seconds)/86400)','maximum_per_day*(@as(f64,seconds)/86400)/(1+2*@as(f64,d))');s=s[:b]+'\n'+extra+s[b:];p.write_text(s)
  p=o/'simulation/planet.zig';s=p.read_text();s=s.replace('Ecology.grow(self.vegetationSnapshot[i], self.temperature[i], self.plantTraits[i].optimum, self.waterMass[i] * self.getKmPerWaterMass(), light, self.averageCarbonDioxideMass > 0, dt)','Ecology.growTough(self.vegetationSnapshot[i], self.temperature[i], self.plantTraits[i].optimum, self.waterMass[i] * self.getKmPerWaterMass(), light, self.averageCarbonDioxideMass > 0, dt,self.plantTraits[i].toughness)');s=s.replace('if (self.vegetationSnapshot[n] < 0.25) continue;','if (self.vegetationSnapshot[n] < 0.25 or self.plantTraits[n].toughness>=1) continue;');s=s.replace('cover += @min(0.08, dt / 86400 * self.vegetationSnapshot[n]);','cover += if(self.plantTraits[n].toughness==0) @min(0.08, dt / 86400 * self.vegetationSnapshot[n]) else @min(0.08, dt / 86400 * self.vegetationSnapshot[n])*(1-self.plantTraits[n].toughness);');p.write_text(s)
  p=o/'simulation/life.zig';s=p.read_text().replace('Foraging.take(planet.vegetation[idx], self.satiety, dt)','Foraging.takeTough(planet.vegetation[idx], self.satiety, dt,planet.plantTraits[idx].toughness)');p.write_text(s)
 # Identical read-only observations in both arms.
 p=o/'simulation/life.zig';s=p.read_text();s='pub var qa_removed:f64=0;pub var qa_credit:f64=0;pub var qa_error:f64=0;\n'+s;s=s.replace('planet.vegetation[idx] = bite.after;','const qa_before=self.satiety;planet.vegetation[idx] = bite.after;');s=s.replace('planet.rabbitMeals += 1;','qa_removed+=bite.eaten;qa_credit+=@as(f64,self.satiety)-qa_before;qa_error+=@abs((@as(f64,self.satiety)-qa_before)-bite.eaten*150);std.debug.assert(@as(f64,self.satiety)-qa_before<=bite.eaten*150);\n                planet.rabbitMeals += 1;');p.write_text(s)
 shutil.copy2(r/'web/tests/sandbox-toughness-qa.zig',o/'qa_sandbox_toughness.zig')
 (out/mode/'hashes.json').write_text(json.dumps({f:hashlib.sha256((o/f).read_bytes()).hexdigest()for f in ['simulation/ecology.zig','simulation/foraging.zig','simulation/life.zig','simulation/planet.zig','qa_sandbox_toughness.zig']},indent=2)+'\n')
